    /* â”€â”€ Parent Chat Cards ("kind of conversations") â”€â”€â”€â”€â”€â”€â”€â”€ */
    .fp-chat-card {
      background: #0f172a;
      border: 1px solid rgba(255,255,255,0.07);
      border-radius: 16px;
      padding: 1.75rem;
      display: flex;
      flex-direction: column;
      gap: 1rem;
      transition: all 0.4s cubic-bezier(0.165, 0.84, 0.44, 1);
      box-shadow: 0 8px 28px rgba(0,0,0,.25);
      position: relative;
      overflow: hidden;
    }
    .fp-chat-card:hover {
      transform: translateY(-3px);
      box-shadow: 0 18px 44px rgba(0,0,0,.35);
      border-color: rgba(255,255,255,0.14);
    }
    /* Geometric accent: top-right circle */
    .fp-chat-card::after {
      content: '';
      position: absolute;
      top: -20px;
      right: -20px;
      width: 100px;
      height: 100px;
      border-radius: 50%;
      background: rgba(255,255,255,0.04);
      pointer-events: none;
    }
    /* Geometric accent: bottom-right ring */
    .fp-chat-card::before {
      content: '';
      position: absolute;
      bottom: -30px;
      right: -10px;
      width: 80px;
      height: 80px;
      border: 2px solid rgba(255,255,255,0.06);
      border-radius: 50%;
      pointer-events: none;
    }
    .fp-chat-header {
      display: flex; align-items: center; gap: 0.75rem;
      padding-bottom: 0.85rem;
      border-bottom: 1px solid rgba(255,255,255,0.08);
      position: relative; z-index: 1;
    }
    .fp-chat-avatar {
      width: 38px; height: 38px; border-radius: 10px;
      display: flex; align-items: center; justify-content: center;
      font-family: 'Nunito', sans-serif;
      font-weight: 800; font-size: 0.78rem;
      color: white; flex-shrink: 0;
    }
    .fp-chat-meta__name {
      font-family: 'Nunito', sans-serif;
      font-size: 0.88rem; font-weight: 800;
      color: rgba(255,255,255,0.95);
    }
    .fp-chat-meta__channel {
      font-family: 'DM Sans', sans-serif;
      font-size: 0.67rem;
      color: rgba(255,255,255,0.4);
      letter-spacing: 0.02em;
    }
    .fp-chat-bubbles {
      display: flex; flex-direction: column; gap: 0.65rem;
      position: relative; z-index: 1;
    }
    .fp-bubble {
      font-family: 'DM Sans', sans-serif;
      font-size: 0.82rem; line-height: 1.55;
      padding: 0.7rem 0.9rem; max-width: 88%;
    }
    .fp-bubble--incoming {
      background: rgba(255,255,255,0.07);
      color: rgba(255,255,255,0.82);
      border-radius: 0 12px 12px 12px;
    }
    .fp-bubble--outgoing {
      background: rgba(244,96,12,0.18);
      color: rgba(255,200,160,0.95);
      border-radius: 12px 0 12px 12px;
      align-self: flex-end; text-align: right;
    }
    .fp-chat-verified {
      display: flex; align-items: center; gap: 0.4rem;
      border-top: 1px solid rgba(255,255,255,0.07);
      padding-top: 0.75rem; margin-top: auto;
      position: relative; z-index: 1;
    }
    .fp-chat-verified span {
      font-family: 'DM Sans', sans-serif;
      font-size: 0.65rem; font-weight: 600;
      letter-spacing: 0.1em; text-transform: uppercase;
      color: #34d399;
    }

    /* â”€â”€ FAQ (Accordion) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */
    .fp-faq { max-width: 780px; margin: 0 auto; }
    .fp-faq details { border-bottom: 1px solid var(--border); }
    .fp-faq summary {
      display: flex; justify-content: space-between; align-items: center;
      padding: 1.35rem 0;
      font-family: 'Nunito', sans-serif; font-size: 1rem; font-weight: 700;
      color: var(--navy); cursor: pointer; list-style: none; gap: 1rem;
      transition: color 0.2s;
    }
    .fp-faq summary::-webkit-details-marker { display: none; }
    .fp-faq summary:hover { color: var(--orange); }
    .fp-faq details[open] summary { color: var(--orange); }
    .fp-faq summary .faq-icon {
      flex-shrink: 0; font-size: 1.4rem; font-weight: 300;
      color: rgba(10,10,10,0.25); transition: transform 0.25s; line-height: 1;
    }
    .fp-faq details[open] summary .faq-icon { transform: rotate(45deg); color: var(--orange); }
    .fp-faq__body {
      font-family: 'DM Sans', sans-serif; font-size: 0.9rem; line-height: 1.7;
      color: var(--mid); padding: 0 0 1.35rem; max-width: 680px;
    }

    /* â”€â”€ Section Label â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */
    .fp-eyebrow {
      font-family: 'DM Sans', sans-serif;
      font-size: 0.68rem; font-weight: 700;
      letter-spacing: 0.15em; text-transform: uppercase;
      color: var(--orange); display: block; margin-bottom: 0.85rem;
    }
    .fp-section-h {
      font-family: 'Nunito', sans-serif;
      font-size: clamp(1.75rem, 3vw, 2.6rem); font-weight: 900;
      color: var(--navy); line-height: 1.1; margin-bottom: 0.85rem;
    }
    .fp-section-sub {
      font-family: 'DM Sans', sans-serif;
      font-size: 0.95rem; line-height: 1.7;
      color: var(--mid); max-width: 560px;
    }

    /* â”€â”€ CTA Banner â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */
    .fp-cta {
      background: var(--navy);
      position: relative; overflow: hidden; padding: 5rem 2rem; text-align: center;
    }
    .fp-cta::before {
      content: ''; position: absolute; inset: 0;
      background: radial-gradient(ellipse 60% 80% at 50% 50%, rgba(244,96,12,0.14) 0%, transparent 70%);
      pointer-events: none;
    }
    .fp-cta__eyebrow {
      font-family: 'DM Sans', sans-serif; font-size: 0.68rem;
      letter-spacing: 0.15em; text-transform: uppercase; color: #fb923c;
      font-weight: 600; margin-bottom: 1rem;
    }
    .fp-cta__h {
      font-family: 'Nunito', sans-serif; font-size: clamp(2rem, 3.5vw, 3rem);
      font-weight: 900; color: white; line-height: 1.1; margin-bottom: 1rem;
    }
    .fp-cta__sub { font-family: 'DM Sans', sans-serif; font-size: 0.95rem; color: rgba(255,255,255,0.55); margin-bottom: 2.5rem; }
    .fp-cta__btns { display: flex; align-items: center; justify-content: center; gap: 1rem; flex-wrap: wrap; }
    .fp-cta__fine { font-family: 'DM Sans', sans-serif; font-size: 0.75rem; color: rgba(255,255,255,0.3); margin-top: 1.5rem; }

    /* â”€â”€ Responsive â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */
    @media (max-width: 1024px) {
      .fp-hero__grid { grid-template-columns: 1fr; padding-bottom: 3rem; }
      .fp-hero__card { transform: none; max-width: 100%; }
      .fp-stats-bar__inner { grid-template-columns: repeat(2,1fr); }
      .fp-stat-item:nth-child(2) { border-right: none; }
      .fp-steps { grid-template-columns: 1fr 1fr; gap: 1.2rem; }
      .fp-step { border-right: none; }
      .fp-split { grid-template-columns: 1fr; gap: 3rem; }
      .fp-split--reverse .fp-split__visual { order: 0; }
      .fp-safety-grid { grid-template-columns: 1fr; }
    }
    @media (max-width: 640px) {
      .fp-steps { grid-template-columns: 1fr; gap: 1rem; }
      .fp-stats-bar__inner { grid-template-columns: 1fr 1fr; }
      .fp-step { border-right: none; border-bottom: none; }
    }
  </style>

</head>
